const fs = require('fs');

let html = fs.readFileSync('standalone-invite.html', 'utf8');

// The messed up encoding generated by my previous script contains %D9%55 instead of %D9%85
// %D9%55 translates to invalid UTF8 character, looking like a question mark and 'U'
html = html.replace(/%D9%55/g, '%D9%85');

fs.writeFileSync('standalone-invite.html', html);
console.log('Fixed encoding in standalone HTML');

// Let's also check if there's any similar issue in App.tsx
let app = fs.readFileSync('src/App.tsx', 'utf8');
if (app.includes('%D9%55')) {
    app = app.replace(/%D9%55/g, '%D9%85');
    fs.writeFileSync('src/App.tsx', app);
    console.log('Fixed encoding in App.tsx');
} else {
    console.log('No encoding issues in App.tsx');
}
